nF(a){return"\u05de"+a},
gKh(){return"\u05d4\u05d7\u05e9\u05d1\u05d5\u05df \u05e9\u05dc\u05da \u05d9\u05d9\u05de\u05d7\u05e7 \u05d9\u05d7\u05d3 \u05e2\u05dd \u05e4\u05e8\u05d5\u05e4\u05d9\u05dc \u05d4\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9 \u05e9\u05dc\u05da: \u05e0\u05d5\u05db\u05d7\u05d5\u05ea, \u05d4\u05e2\u05e8\u05d5\u05ea, \u05d0\u05d9\u05e9\u05d5\u05e8\u05d9\u05dd \u05e8\u05e4\u05d5\u05d0\u05d9\u05d9\u05dd, \u05d4\u05e6\u05d4\u05e8\u05d5\u05ea \u05d1\u05e8\u05d9\u05d0\u05d5\u05ea, \u05ea\u05d5\u05e6\u05d0\u05d5\u05ea \u05d5\u05e1\u05d9\u05de\u05d5\u05e0\u05d9 \u05de\u05e9\u05d9\u05de\u05d5\u05ea. \u05dc\u05d0 \u05e0\u05d9\u05ea\u05df \u05dc\u05d1\u05d8\u05dc \u05e4\u05e2\u05d5\u05dc\u05d4 \u05d6\u05d5."},
gSP(){return"\u05d4\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9 \u05d9\u05db\u05d5\u05dc \u05dc\u05e9\u05de\u05d5\u05e8 \u05d0\u05ea \u05d4\u05d3\u05e8\u05db\u05d5\u05df \u05db-PDF."},
gwF(){return"\u05ea\u05d0\u05e8\u05d9\u05da \u05d4\u05dc\u05d9\u05d3\u05d4 \u05de\u05d2\u05d9\u05e2 \u05de\u05d9\u05d9\u05d1\u05d5\u05d0 \u05de\u05d0\u05e7\u05e1\u05dc \u05d0\u05d5 \u05de\u05d4\u05e9\u05d0\u05dc\u05d5\u05df \u05e9\u05dc \u05d4\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9. \u05d1\u05dc\u05d9 \u05ea\u05d0\u05e8\u05d9\u05da \u05d0\u05d9\u05df \u05d1\u05d3\u05d9\u05e7\u05ea \u05d4\u05ea\u05d0\u05de\u05d4 \u05dc\u05ea\u05d7\u05e8\u05d5\u05d9\u05d5\u05ea \u05dc\u05e4\u05d9 \u05e9\u05e0\u05ea\u05d5\u05df."},
gJi(){return"\u05e7\u05d8\u05d2\u05d5\u05e8\u05d9\u05d9\u05ea \u05de\u05e9\u05e7\u05dc: \u05d8\u05d1\u05dc\u05ea IBJJF 2021 \u05de\u05d5\u05d5\u05d9\u05e7\u05d9\u05e4\u05d3\u05d9\u05d4, \u05dc\u05d0\u05d9\u05de\u05d5\u05ea (\u05e2\u05d5\u05d3 \u05dc\u05d0 \u05d4\u05d5\u05e9\u05d5\u05d5\u05ea\u05d4 \u05dc\u05d8\u05d1\u05dc\u05d4 \u05d4\u05e8\u05e9\u05de\u05d9\u05ea \u05e9\u05dc IBJJF)"},
gBQ(){return"\u05d8\u05dc\u05e4\u05d5\u05df"},
gMz(){return"\u05e4\u05dc\u05d0\u05d9\u05d9\u05e8 \u05d0\u05d7\u05d3 \u05e9\u05dc \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df \u05dc\u05db\u05d5\u05dc\u05dd. \u05d4\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea, \u05d4\u05e9\u05e2\u05d5\u05ea, \u05d4\u05e1\u05e0\u05d9\u05e4\u05d9\u05dd \u05d5\u05d4\u05de\u05d0\u05de\u05e0\u05d9\u05dd \u05e0\u05dc\u05e7\u05d7\u05d9\u05dd \u05de\u05e0\u05ea\u05d5\u05e0\u05d9 \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df \u05d5\u05de\u05ea\u05e2\u05d3\u05db\u05e0\u05d9\u05dd \u05dc\u05d1\u05d3. \u05d4\u05db\u05e4\u05ea\u05d5\u05e8 \xab\u05d4\u05d6\u05de\u05d9\u05e0\u05d5 \u05d7\u05d1\u05e8\xbb \u05de\u05d5\u05e4\u05d9\u05e2 \u05dc\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd \u05e8\u05e7 \u05d0\u05d7\u05e8\u05d9 \u05e9\u05d0\u05d9\u05e9\u05e8\u05ea\u05dd."},
gXb(){return"\u05e0\u05d6\u05db\u05d9\u05e8 \u05dc\u05da \u05d1\u05d9\u05d5\u05dd \u05d4\u05d0\u05d9\u05de\u05d5\u05df \u05e9\u05dc \u05d4\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05e9\u05dc\u05da, \u05d5\u05e0\u05d2\u05d9\u05d3 \u05de\u05ea\u05d9 \u05dc\u05e6\u05d0\u05ea \u05dc\u05e4\u05d9 \u05d4\u05d6\u05de\u05df \u05e9\u05dc\u05d5\u05e7\u05d7 \u05dc\u05d4\u05d2\u05d9\u05e2. \u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9\u05dd \u05de\u05e7\u05d1\u05dc\u05d9\u05dd \u05ea\u05d6\u05db\u05d5\u05e8\u05d5\u05ea \u05de\u05e9\u05dc\u05d4\u05dd \u05d1\u05d8\u05dc\u05e4\u05d5\u05df \u05e9\u05dc\u05d4\u05dd."},
gY6(){return"\u05d4\u05e1\u05e4\u05d5\u05e8\u05d8\u05d0\u05d9 \u05dc\u05d0 \u05d0\u05d9\u05e9\u05e8 \u05d5\u05d5\u05d0\u05d8\u05e1\u05d0\u05e4 \u05d1\u05e9\u05d0\u05dc\u05d5\u05df. \u05d4\u05d4\u05d5\u05d3\u05e2\u05d4 \u05de\u05d7\u05db\u05d4 \u05d1-Jita."},
gQj(){return"\u05d2\u05f3\u05d9\u05d8\u05d4 \u05e7\u05d9\u05d5\u05b9\u05d0\u05b5\u05d9 \u2013 \u05ea\u05d5\u05e2\u05dc\u05ea \u05d4\u05d3\u05d3\u05d9\u05ea \u05d5\u05e9\u05d2\u05e9\u05d5\u05d2 \u05de\u05e9\u05d5\u05ea\u05e3"},
gxO(){return"\u05db\u05dc \u05d4\u05e1\u05e0\u05d9\u05e4\u05d9\u05dd (\u05db\u05dc \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df)"},
gxP(){return"\u05de\u05d0\u05de\u05df \u05e8\u05d0\u05e9\u05d9: \u05db\u05dc \u05d4\u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05d1\u05e1\u05e0\u05d9\u05e4\u05d9\u05dd \u05e9\u05e0\u05d1\u05d7\u05e8\u05d5, \u05d4\u05d6\u05de\u05e0\u05d4 \u05d5\u05d0\u05d9\u05e9\u05d5\u05e8 \u05e9\u05dc \u05d4\u05d5\u05e8\u05d9\u05dd \u05d5\u05de\u05d0\u05de\u05e0\u05d9\u05dd, \u05e9\u05d9\u05d5\u05da \u05e7\u05d1\u05d5\u05e6\u05d5\u05ea \u05dc\u05de\u05d0\u05de\u05e0\u05d9\u05dd. \u05d1\u05dc\u05d9 \u05d4\u05d2\u05d3\u05e8\u05d5\u05ea \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df, \u05de\u05e0\u05d4\u05dc\u05d9\u05dd, \u05e4\u05dc\u05d0\u05d9\u05d9\u05e8 \u05d5\u05d3\u05e3 \u05d4\u05de\u05d5\u05e2\u05d3\u05d5\u05df."},
